                state.texture = Gdk.Texture.new_from_filename(path);
            } catch (e) {
                logger.error(CAT, `captureWindow: Gdk.Texture.new_from_filename ${path}`, e);
            }
            loadTextureAll(path, pictures);
        }
    });
}

