import WindowManager from '#/lib/services/state/windowManager';
import {useSettings} from '#/lib/settings';
import PaletteGenerator from '#/style/palette';
import Adw from 'gi://Adw?version=1';
import Gtk from 'gi://Gtk?version=4.0';
import {TEMP_MIN, TEMP_MAX} from '#/lib/services/display/nightLight';

export default () => {
    const settings = useSettings().general;
    const fileDialog = Gtk.FileDialog.new();
    fileDialog.set_default_filter(new Gtk.FileFilter({mimeTypes: ['image/*']}));

    return (
        <>
            <Adw.PreferencesGroup
                title={'Appearance'}
                description={'Set cosmetic options'}
            >
                <Adw.ActionRow title={'System Theme'}>
                    <Adw.ToggleGroup
                        $type="suffix"
                        cssClasses={['round']}
                        valign={Gtk.Align.CENTER}
                        onNotifyActiveName={self => {
                            const map: Record<string, number> = {
                                auto: 0,
                                light: 1,
                                dark: 2,
                            };
                            settings.setColorScheme(map[self.activeName ?? 'auto'] ?? 0);
                        }}
                        // eslint-disable-next-line @typescript-eslint/no-explicit-any
                        $={self => {
                            const v = (settings.colorScheme as any).peek();
                            self.activeName = ['auto', 'light', 'dark'][v] ?? 'auto';
                            (settings.colorScheme as any).subscribe((v: number) => {
                                self.activeName = ['auto', 'light', 'dark'][v] ?? 'auto';
                            });
                        }}
                    >
                        <Adw.Toggle
                            name={'auto'}
                            label={'Auto'}
                            iconName={'night-light-symbolic'}
                        />
                        <Adw.Toggle
                            name={'light'}
                            label={'Light'}
                            iconName={'weather-clear-symbolic'}
                        />

